import pytest
import cart

# ---------- utility helper for floating comparison
from math import isclose

def assert_close(a, b, eps=1e-9):
    assert isclose(a, b, abs_tol=eps), f"{a} != {b}"

# ---------- apply_discount tests
@pytest.mark.parametrize("price,percent,result", [
    (200.0, 15, 170.0),          # example from spec
    (100.0, 0, 100.0),           # no discount
    (50.0, 100, 0.0),            # full discount
])
def test_apply_discount_valid(price, percent, result):
    assert cart.apply_discount(price, percent) == result

@pytest.mark.parametrize("price,percent", [
    (-10, 20),   # negative price
    (50, -5),    # negative percent
    (50, 105),   # percent >100
])
def test_apply_discount_invalid(price, percent):
    with pytest.raises(ValueError):
        cart.apply_discount(price, percent)

# ---------- bulk_discount_percent tests
@pytest.mark.parametrize("quantity,expected", [
    (5, 0),       # below 10
    (10, 5),      # exactly 10
    (49, 5),      # just below 50
    (50, 10),     # exactly 50
    (99, 10),     # just below 100
    (100, 15),    # exactly 100
    (200, 15),    # above 100
])
def test_bulk_discount_percent(quantity, expected):
    assert cart.bulk_discount_percent(quantity) == expected

@pytest.mark.parametrize("quantity", [0, -5, 3.5])
def test_bulk_discount_invalid(quantity):
    with pytest.raises(ValueError):
        cart.bulk_discount_percent(quantity)

# ---------- parse_coupon tests
@pytest.mark.parametrize("code,expected", [
    ("SAVE10", 10),
    ("save20", 20),
    ("   SaVe5   ", 5),
])
def test_parse_coupon_valid(code, expected):
    assert cart.parse_coupon(code) == expected

@pytest.mark.parametrize("code", [
    "SAVE0",            # N <1
    "SAVE51",           # N >50
    "NOTC10",           # wrong prefix
    " SAVE 10 ",        # space inside code
    "" ,                # empty string
])
def test_parse_coupon_invalid(code):
    with pytest.raises(ValueError):
        cart.parse_coupon(code)

# ---------- shipping_fee tests
@pytest.mark.parametrize("subtotal,member,expected", [
    (0.0, False, 60),
    (500, True, 30),   # member half
    (999.99, False, 60),
    (1000, False, 0),
    (1500, True, 0),   # free shipping
])
def test_shipping_fee(subtotal, member, expected):
    assert cart.shipping_fee(subtotal, member) == expected

@pytest.mark.parametrize("subtotal", [-1.0, -100])
def test_shipping_fee_invalid(subtotal):
    with pytest.raises(ValueError):
        cart.shipping_fee(subtotal)

# ---------- Cart tests
class TestCart:
    def setup_method(self):
        self.c = cart.Cart()

    def test_add_and_items(self):
        self.c.add_item("apple", 1.0, 3)
        assert self.c.items() == {"apple": 3}
        # adding same item increases quantity
        self.c.add_item("apple", 1.0, 2)
        assert self.c.items() == {"apple": 5}

    def test_add_same_name_different_price_raises(self):
        self.c.add_item("banana", 0.5, 1)
        with pytest.raises(ValueError):
            self.c.add_item("banana", 0.6, 2)

    def test_add_invalid_params(self):
        with pytest.raises(ValueError):
            self.c.add_item("orange", -1.0, 1)
        with pytest.raises(ValueError):
            self.c.add_item("orange", 1.0, 0)

    def test_remove_item(self):
        self.c.add_item("tshirt", 20.0, 2)
        self.c.remove_item("tshirt", 1)
        assert self.c.items() == {"tshirt": 1}
        # removing remaining quantity removes item
        self.c.remove_item("tshirt", 1)
        assert self.c.items() == {}

    def test_remove_nonexistent_raises(self):
        with pytest.raises(KeyError):
            self.c.remove_item("nonexistent", 1)

    def test_subtotal_with_bulk_discount(self):
        # 12 apples at $2 each -> bulk discount 5%
        self.c.add_item("apple", 2.0, 12)
        expected = 2.0 * 12 * (1 - 0.05)  # 22.8
        assert_close(self.c.subtotal(), round(expected, 2))

    def test_subtotal_rounding_and_empty_cart(self):
        assert self.c.subtotal() == 0
        # add item that after discount gives fraction .005
        self.c.add_item("pen", 1.333, 3)  # unit price arbitrary
        # compute manually with bulk_discount 0
        subtotal = round(1.333 * 3, 2)
        assert_close(self.c.subtotal(), subtotal)

    def test_total_without_coupon_and_non_member(self):
        self.c.add_item("book", 30.0, 1)   # no bulk discount
        total = 30.0 + cart.shipping_fee(30.0, member=False)
        assert_close(self.c.total(), round(total, 2))

    def test_total_with_coupon_and_member(self):
        self.c.add_item("lamp", 50.0, 2)   # no bulk discount
        subtotal = 100.0
        coupon_discount = cart.apply_discount(subtotal, cart.parse_coupon("SAVE10"))  # 90
        shipping = cart.shipping_fee(coupon_discount, member=True)
        expected_total = round(coupon_discount + shipping, 2)
        assert_close(self.c.total(member=True, coupon="SAVE10"), expected_total)

    def test_total_empty_cart(self):
        assert self.c.total() == 0

    def test_total_invalid_coupon_raises(self):
        self.c.add_item("item", 5.0, 1)
        with pytest.raises(ValueError):
            self.c.total(coupon="BADCODE")
"

